    47  void
    48  UA_Notification_delete(UA_Subscription *sub, UA_MonitoredItem *mon,
    49                         UA_Notification *n) {
    50      if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_CHANGENOTIFY) {
    51          UA_DataValue_deleteMembers(&n->data.value);
    52          --sub->dataChangeNotifications;
    53  #ifdef UA_ENABLE_SUBSCRIPTIONS_EVENTS
    54      } else if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_EVENTNOTIFY) {
    55          UA_EventFieldList_deleteMembers(&n->data.event.fields);
    56          /* EventFilterResult currently isn't being used
    57           * UA_EventFilterResult_delete(notification->data.event->result); */
    58          --sub->eventNotifications;
    59  #endif
    60      } else if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_STATUSNOTIFY) {
    61          --sub->statusChangeNotifications;
    62      }
    63
    64      TAILQ_REMOVE(&mon->queue, n, listEntry);
    65      --mon->queueSize;
    66
    67      TAILQ_REMOVE(&sub->notificationQueue, n, globalEntry);
    68      --sub->notificationQueueSize;
    69
    70      UA_free(n);
    71  }
