    73  UA_Subscription *
    74  UA_Subscription_new(UA_Session *session, UA_UInt32 subscriptionId) {
    75      /* Allocate the memory */
    76      UA_Subscription *newSub =
    77          (UA_Subscription*)UA_calloc(1, sizeof(UA_Subscription));
    78      if(!newSub)
    79          return NULL;
    80
    81      /* Remaining members are covered by calloc zeroing out the memory */
    82      newSub->session = session;
    83      newSub->subscriptionId = subscriptionId;
    84      newSub->state = UA_SUBSCRIPTIONSTATE_NORMAL; /* The first publish response is sent immediately */
    85      /* Even if the first publish response is a keepalive the sequence number is 1.
    86       * This can happen by a subscription without a monitored item (see CTT test scripts). */
    87      newSub->nextSequenceNumber = 1;
    88      TAILQ_INIT(&newSub->retransmissionQueue);
    89      TAILQ_INIT(&newSub->notificationQueue);
    90      return newSub;
    91  }
