   128  UA_StatusCode
   129  UA_Subscription_deleteMonitoredItem(UA_Server *server, UA_Subscription *sub,
   130                                      UA_UInt32 monitoredItemId) {
   131      /* Find the MonitoredItem */
   132      UA_MonitoredItem *mon;
   133      LIST_FOREACH(mon, &sub->monitoredItems, listEntry) {
   134          if(mon->monitoredItemId == monitoredItemId)
   135              break;
   136      }
   137      if(!mon)
   138          return UA_STATUSCODE_BADMONITOREDITEMIDINVALID;
   139
   140      /* Remove the MonitoredItem */
   141      LIST_REMOVE(mon, listEntry);
   142      sub->monitoredItemsSize--;
   143
   144      /* Remove content and delayed free */
   145      UA_MonitoredItem_delete(server, mon);
   146
   147      return UA_STATUSCODE_GOOD;
   148  }
